export const isPhraseId = (id: unknown): id is number =>
    typeof id === 'number' && Math.floor(id) === id && id >= 0 && id < CHAT_PHRASES.length;
export const isStickerId = (id: unknown): id is number =>
    typeof id === 'number' && Math.floor(id) === id && id >= 0 && id < CHAT_STICKERS.length;

/** True when phrase `id` may be said in `scope` (stickers are allowed in every scope). */
export function phraseInScope(id: number, scope: ChatScope): boolean {
    if (!isPhraseId(id)) return false;
    return CHAT_PHRASES[id].scopes.indexOf(scope) !== -1;
}

