export type ChatTier = 'text' | 'quick';
export type ChatAgeBand = 'under16' | '16-17' | '18+';

/** One account's tier: free text only for a registered account whose stored band is 16 or older. */
export function accountChatTier(band: ChatAgeBand | null | undefined, registered: boolean): ChatTier {
    return registered && (band === '16-17' || band === '18+') ? 'text' : 'quick';
}

/** A thread's tier: the strictest participant wins (an empty list is quick). */
export function threadChatTier(tiers: ReadonlyArray<ChatTier>): ChatTier {
    if (!tiers.length) return 'quick';
    for (let i = 0; i < tiers.length; i += 1) if (tiers[i] !== 'text') return 'quick';
    return 'text';
}

/** A 16-17 and an 18+ side in one text thread: the age and meeting probe filter applies (§2.4 step 8). */
export function crossesAdultLine(bands: ReadonlyArray<ChatAgeBand | null | undefined>): boolean {
    return bands.indexOf('16-17') !== -1 && bands.indexOf('18+') !== -1;
}

