/**
 * A player's avatar as every list, card and party view carries it (§7.3). `i`: `h:<heroId>`, `c:<catId>` or
 * `i:<iconId>`; `img`: the cat art URL (NFT bucket host only); `f` frame id; `t` title id; `r` ranked tier id.
 */
export interface AvatarView {
    i: string;
    img?: string;
    f?: string;
    t?: string;
    r?: string;
}

export const AVATAR_ICON_RE = /^(h:[a-z][a-z0-9]{0,23}|c:[a-f0-9]{24}|i:[a-z0-9._-]{1,48})$/;
export const AVATAR_ITEM_RE = /^(frame|title)\.[a-z0-9._-]{1,48}$/;
/** Only cat art from the Token Tails NFT bucket may be shown as an avatar image (party-cards.ts PARTY_ART_HOST). */
export const AVATAR_ART_HOST = 'tokentails-nfts.fra1.cdn.digitaloceanspaces.com';
export const AVATAR_IMG_RE =
    /^https:\/\/tokentails-nfts\.fra1\.cdn\.digitaloceanspaces\.com\/[A-Za-z0-9._~\/%-]{1,250}$/;

/** A trusted shape check of an AvatarView (the client renders only what passes). */
export function isAvatarView(v: unknown): v is AvatarView {
    if (!v || typeof v !== 'object') return false;
    const o = v as Record<string, unknown>;
    if (typeof o.i !== 'string' || !AVATAR_ICON_RE.test(o.i)) return false;
    if (o.img !== undefined && (typeof o.img !== 'string' || !AVATAR_IMG_RE.test(o.img))) return false;
    if (o.f !== undefined && (typeof o.f !== 'string' || !/^frame\.[a-z0-9._-]{1,48}$/.test(o.f))) return false;
    if (o.t !== undefined && (typeof o.t !== 'string' || !/^title\.[a-z0-9._-]{1,48}$/.test(o.t))) return false;
    if (o.r !== undefined && (typeof o.r !== 'string' || !/^[a-z0-9_-]{1,24}$/.test(o.r))) return false;
    return true;
}
